def mark_existing_addresses(apps, schema_editor):
    """Accounts that exist now entered their address before addresses were verified: they
    may still receive password reset links (see recovery.trusted_email). Every account gets a
    profile for that, with the activity it had (for the deletion of inactive accounts)."""
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    UserProfile = apps.get_model("brick_dnn_core", "UserProfile")
    UserProfile.objects.update(email_legacy=True)
    missing = User.objects.filter(profile__isnull=True)
    UserProfile.objects.bulk_create(
        [
            UserProfile(
                user_id=user.pk,
                last_active_at=user.last_login or user.date_joined,
                email_legacy=True,
            )
            for user in missing.only("pk", "last_login", "date_joined")
        ],
        batch_size=500,
    )


